  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C48"],
      "claim": "In three fasted adult male volunteers, sodium saccharin had an absolute oral bioavailability of 0.84±0.08 vs i.v., well above the 20% threshold."
    },
    {
      "card_ids": ["C33"],
      "claim": "Rufinamide absolute oral bioavailability in humans was reported as 85%, supporting high bioavailability."
    },
    {
      "card_ids": ["C15"],
      "claim": "Penclomedine oral bioavailability in patients with solid tumors ranged from 28% to 98% (median 73%) vs i.v., with all reported values above 20%."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All transferred evidence molecules have reported oral bioavailability values above 20%, including the lowest observed values (28% penclomedine and 35–55% cladribine), consistently supporting high bioavailability at the F≥20% threshold.",
  "evidence_gaps": [
    "Molecule 9 provides only qualitative 'high bioavailability' without a numeric F value and was not used as primary support.",
    "Some records come from special populations or altered conditions, but the primary absolute records in ordinary conditions consistently exceed the threshold."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C48", "C33", "C15"],
  "revision_action": "initial",
  "supportive_card_ids": ["C48", "C33", "C15"]
}

